const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, Authorization, x-client-info, X-Client-Info, apikey, ApiKey, content-type, Content-Type, cache-control, Cache-Control, pragma, Pragma, expires, Expires, x-edge-function-name, X-Edge-Function-Name, accept, Accept',
  'Access-Control-Allow-Methods': 'POST, OPTIONS'
};

function parseDataUri(data: string) {
  const m = data.match(/^data:([^;]+);base64,(.+)$/i);
  if (m) return { mime: m[1], base64: m[2] };
  return { mime: 'image/png', base64: data };
}

function guessMimeFromPath(path: string) {
  const lower = path.toLowerCase();
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.webp')) return 'image/webp';
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg';
  return 'image/jpeg';
}

function normalizeAwningType(input: unknown): 'knikarm' | 'markies' | 'uitvalscherm' {
  const raw = (typeof input === 'string') ? input.toLowerCase().trim() : '';
  if (raw.includes('markies')) return 'markies';
  if (raw.includes('uitval')) return 'uitvalscherm';
  return 'knikarm';
}

async function readFileAsBase64Inline(path: string): Promise<{ inlineData: { mimeType: string; data: string } } | null> {
  try {
    const bytes = await Deno.readFile(path);
    let binary = '';
    const chunkSize = 32768;
    for (let i = 0; i < bytes.byteLength; i += chunkSize) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize) as any);
    }
    const base64 = btoa(binary);
    const mime = guessMimeFromPath(path);
    return { inlineData: { mimeType: mime, data: base64 } };
  } catch (e) {
    console.error(`[ERROR] Failed to read file ${path}:`, e);
    return null;
  }
}

// Updated to support chat history
async function callGeminiChat(model: string, contents: any[], imageConfig?: any, temperature: number = 0.1) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
  const body: any = {
    contents: contents,
    generationConfig: {
      temperature: temperature,
      topK: 32,
      topP: 0.8,
      maxOutputTokens: 4096,
      responseModalities: ["IMAGE"]
    }
  };

  // Do not set mediaResolution here; image models reject it.

  // FIXED: gemini-2.5-flash-image doesn't support imageSize parameter, only aspectRatio
  if (imageConfig) {
    if (model === 'gemini-2.5-flash-image') {
      // Only pass aspectRatio for flash model, skip imageSize
      body.generationConfig.imageConfig = { aspectRatio: imageConfig.aspectRatio };
    } else {
      body.generationConfig.imageConfig = imageConfig;
    }
  }

  console.log(`[DEBUG] calling Gemini Chat with model ${model}, history length: ${contents.length}`);
  // console.log(`[DEBUG] Request Body: ${JSON.stringify(body)}`); // Uncomment for deep debugging

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 35000);

  try {
    const res = await fetch(`${url}?key=${GEMINI_API_KEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (!res.ok) {
      const txt = await res.text();
      console.error(`Gemini error ${res.status}: ${txt}`);
      throw new Error(`Gemini error: ${res.status} ${txt}`);
    }
    return await res.json();
  } catch (error: any) {
    clearTimeout(timeoutId);
    if (error.name === 'AbortError') {
      throw new Error(`Gemini request timed out after 60s`);
    }
    throw error;
  }
}

function extractImage(result: any) {
  if (result && Array.isArray(result.candidates)) {
    for (const c of result.candidates) {
      if (c && c.content && Array.isArray(c.content.parts)) {
        for (const p of c.content.parts) {
          const img = (p as any).inlineData || (p as any).inline_data;
          if (img && img.data) {
            let mime = img.mimeType || img.mime_type || 'image/png';
            if (mime === 'image/jpg') mime = 'image/jpeg';
            if (!mime.startsWith('image/')) mime = 'image/png';
            return `data:${mime};base64,${img.data}`;
          }
        }
      }
    }
  }
  return null;
}

// Quick preservation check to fail fast
async function quickPreservationCheck(originalBase64: string, generatedBase64: string) {
  const url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent";
  const prompt = `Compare these two images. Is Image 2 the SAME HOUSE from the SAME ANGLE as Image 1, with only an awning added?

Answer with ONLY: YES or NO

If NO, briefly explain what changed (different house, different angle, cropped, etc.)`;

  const body = {
    contents: [{
      parts: [
        { text: prompt },
        { inlineData: { mimeType: 'image/png', data: originalBase64 } },
        { inlineData: { mimeType: 'image/png', data: generatedBase64 } }
      ]
    }],
    generationConfig: { temperature: 0.1, maxOutputTokens: 100 }
  };

  try {
    const res = await fetch(`${url}?key=${GEMINI_API_KEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const j = await res.json();
    const text = j.candidates?.[0]?.content?.parts?.[0]?.text || "NO";
    const passed = text.trim().toUpperCase().startsWith("YES");
    return { passed, reason: text };
  } catch (e) {
    console.error("Preservation check failed", e);
    return { passed: false, reason: "Check failed" };
  }
}

// Unified Quality Scoring Function
async function evaluateImageQuality(originalBase64: string, referenceBase64: string, generatedBase64: string, colorSwatchBase64: string | null = null, awningType: string = 'knikarm', anchors?: { x_left: number; x_right: number; y: number; width_px: number }) {
  const url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent";

  const isMarkies = awningType === 'markies';
  const isUitval = awningType === 'uitvalscherm';

  const inferMimeFromBase64 = (b64: string): string => {
    try {
      const bytes = base64ToBytes(b64.slice(0, 512));
      if (bytes.length >= 8 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4E && bytes[3] === 0x47) return "image/png";
      if (bytes.length >= 3 && bytes[0] === 0xFF && bytes[1] === 0xD8 && bytes[2] === 0xFF) return "image/jpeg";
      if (bytes.length >= 6 && String.fromCharCode(bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5]) === "GIF89a") return "image/gif";
      if (bytes.length >= 6 && String.fromCharCode(bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5]) === "GIF87a") return "image/gif";
      return "image/png";
    } catch (_) {
      return "image/png";
    }
  };

  const promptText = `
  Analyze Generated Image (last) vs Original (first) & Reference (second).
  Respond with valid JSON only.
  ${colorSwatchBase64 ? "Check color accuracy using Swatch (Image 3)." : ""}
  ${anchors ? `Verify placement against anchors: LEFT X=${anchors.x_left}, RIGHT X=${anchors.x_right}, TOP Y=${anchors.y}, WIDTH=${anchors.width_px}.` : ''}
  
  CRITERIA (0-10):
  - Placement: 0 if misaligned.
  - Preservation: 0 if house changed.
  - No Red Line: 10 if gone, 0 if visible.
  - Shape: ${isMarkies ? 'MARKIES (Curved)' : isUitval ? 'UITVALSCHERM (Triangle, Diagonal Arms, Visible Wall Brackets at arm origins)' : 'KNIKARM (Horizontal)'}
  - Hardware: Arms must be visible and attach via visible wall-mounted brackets/plates with pivot hubs (uitvalscherm).
  - Front Bar: Slim, rounded HALF-CYLINDER voorlijst (NOT boxy), fabric-dominant view.
  - Color: Match swatch.

  STYLE CLASSIFICATION:
  - 'uitvalscherm': TRIANGLE profile, STRAIGHT diagonal arms, STEEP slope, arms MUST attach to VISIBLE wall-mounted brackets/plates with pivot hubs. Arms cannot float.
  - 'knikarm': Folding arms, horizontal.
  
  Provide a style_match_score (0-10). 10 = perfect match to expected type.

  JSON Structure:
  {
    "placement_score": number,
    "preservation_score": number,
    "no_red_line_score": number,
    "extension_score": number,
    "color_score": number,
    "style_match_score": number,
    "style_pred": "markies" | "knikarm" | "uitvalscherm" | "closed" | "unknown",
    "arms_visible": boolean,
    "brackets_visible": boolean,
    "front_bar_slim": boolean,
    "explanation": "short string"
  }
  `;

  const originalMime = inferMimeFromBase64(originalBase64);
  const referenceMime = inferMimeFromBase64(referenceBase64);
  const generatedMime = inferMimeFromBase64(generatedBase64);
  const swatchMime = colorSwatchBase64 ? inferMimeFromBase64(colorSwatchBase64) : null;

  const parts = [
    { text: promptText },
    { inlineData: { mimeType: originalMime, data: originalBase64 } },
    { inlineData: { mimeType: referenceMime, data: referenceBase64 } }
  ];

  if (colorSwatchBase64) {
    parts.push({ inlineData: { mimeType: swatchMime || 'image/png', data: colorSwatchBase64 } });
  }

  // Add the structure ref just in case, but QA focuses on color/swatch
  // Actually, let's keep it simple. Structure is checked visually.

  parts.push({ inlineData: { mimeType: generatedMime, data: generatedBase64 } });

  const body = {
    contents: [{
      parts: parts
    }],
    generationConfig: {
      temperature: 0.1,
      topK: 32,
      topP: 0.8,
      maxOutputTokens: 4096,
      responseMimeType: "application/json"
    }
  };

  try {
    const res = await fetch(`${url}?key=${GEMINI_API_KEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });

    if (!res.ok) return { placement_score: 0, preservation_score: 0, no_red_line_score: 0, extension_score: 0, color_score: 0, explanation: "Verification check failed: " + res.statusText };

    const j = await res.json();
    let parsed = { placement_score: 0, preservation_score: 0, no_red_line_score: 0, extension_score: 0, color_score: 0, explanation: "Could not parse response" };

    if (j.candidates && j.candidates[0]) {
      const c = j.candidates[0];
      if (c.content && c.content.parts) {
        // Concatenate all text parts to avoid truncation
        const allText = c.content.parts.filter((p: any) => typeof p.text === 'string').map((p: any) => p.text).join('\n');
        if (allText) {
          const clean = allText.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();
          const m = clean.match(/\{[\s\S]*\}/);
          if (m) {
            try {
              parsed = JSON.parse(m[0]);
            } catch (e) {
              console.error(`[ERROR] JSON parse failed. Raw text: ${clean}`, e);
            }
          } else {
            console.warn(`[WARN] No JSON found in response. Raw text: ${clean}`);
          }
        } else {
          console.warn(`[WARN] No text parts in QA response.`);
        }
      }
    }
    return parsed;
  } catch (e) {
    return { placement_score: 0, preservation_score: 0, no_red_line_score: 0, extension_score: 0, color_score: 0, explanation: "Error during verification: " + (e as Error).message };
  }
}

function base64ToBytes(base64: string) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function getImageDimensionsFromBase64(base64: string) {
  try {
    const bytes = base64ToBytes(base64);
    const img = await Image.decode(bytes);
    return { width: img.width, height: img.height };
  } catch (e) {
    console.error("Error decoding image dimensions:", e);
    return { width: 0, height: 0 };
  }
}

async function detectRedLineAnchors(baseImageBase64: string, imgWidth: number, imgHeight: number) {
  const url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent";
  const prompt = `Identify the user-drawn horizontal RED markers in Image 1.
Return exact pixel anchors relative to the image pixel grid:
{"x_left": number, "x_right": number, "y": number, "width_px": number}
Rules:
- The user may draw ONE continuous red line OR TWO separate red segments indicating LEFT and RIGHT endpoints.
- If TWO segments exist at approximately the SAME Y (±3px), set x_left to the LEFTMOST red pixel across both segments, x_right to the RIGHTMOST red pixel, and y to the common Y (use the top edge). width_px = x_right - x_left.
- If ONE continuous line exists, use its leftmost and rightmost red pixels, y = top edge.
- Ignore tiny red artifacts or slanted markings.
- Respond ONLY with JSON.`;

  const body = {
    contents: [{
      parts: [
        { text: prompt },
        { inlineData: { mimeType: 'image/png', data: baseImageBase64 } }
      ]
    }],
    generationConfig: { temperature: 0.1, topK: 16, topP: 0.8, maxOutputTokens: 512, responseMimeType: "application/json" }
  };

  try {
    const res = await fetch(`${url}?key=${GEMINI_API_KEY}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    if (!res.ok) return null;
    const j = await res.json();
    let parsed: any = null;
    const c = j.candidates?.[0];
    const txt = c?.content?.parts?.[0]?.text || '';
    if (typeof txt === 'string') {
      const cleanText = txt.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();
      const m = cleanText.match(/\{[\s\S]*\}/);
      if (m) {
        try { parsed = JSON.parse(m[0]); } catch (_) { parsed = null; }
      }
    }
    if (!parsed || typeof parsed.x_left !== 'number' || typeof parsed.x_right !== 'number' || typeof parsed.y !== 'number' || typeof parsed.width_px !== 'number') return null;
    if (parsed.x_left < 0 || parsed.x_right > imgWidth || parsed.y < 0 || parsed.y > imgHeight) return null;
    return parsed;
  } catch (_) {
    return null;
  }
}

// Fallback: Detect red line anchors via pixel scanning (no model dependency)
async function detectRedLineAnchorsPixel(baseImageBase64: string) {
  try {
    const img = await Image.decode(base64ToBytes(baseImageBase64));
    let best = { y: -1, minX: 0, maxX: 0, width: 0, count: 0 };
    for (let y = 0; y < img.height; y++) {
      let minX = img.width, maxX = -1, count = 0;
      for (let x = 0; x < img.width; x++) {
        const color = img.getPixelAt(x, y);
        const r = (color >> 24) & 0xFF;
        const g = (color >> 16) & 0xFF;
        const b = (color >> 8) & 0xFF;
        
        // Strict Red Logic synced with removeRedLinesFromBase64 to avoid detecting bricks
        if (r >= 200 && g < 80 && b < 80 && (r - Math.max(g, b) > 100)) {
          count++;
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
        }
      }
      if (count > 0 && maxX >= 0) {
        const width = maxX - minX;
        // Prefer the row with largest width; break ties with higher count
        if (width > best.width || (width === best.width && count > best.count)) {
          best = { y, minX, maxX, width, count };
        }
      }
    }
    if (best.y < 0 || best.width < 20) return null;
    return { x_left: best.minX, x_right: best.maxX, y: best.y, width_px: best.width };
  } catch (_) {
    return null;
  }
}

function rgbDiff(a: number, b: number) {
  const ar = (a >> 24) & 0xFF, ag = (a >> 16) & 0xFF, ab = (a >> 8) & 0xFF;
  const br = (b >> 24) & 0xFF, bg = (b >> 16) & 0xFF, bb = (b >> 8) & 0xFF;
  return Math.abs(ar - br) + Math.abs(ag - bg) + Math.abs(ab - bb);
}

async function measureAwningWidthUsingDiff(baseBase64: string, genBase64: string, anchors: { x_left: number; x_right: number; y: number; width_px: number }) {
  try {
    const genImg = await Image.decode(base64ToBytes(genBase64));

    // We measure the awning width by detecting pixels that differ significantly from the "background" wall color.
    // We assume the pixels just outside the expected awning range (left/right) are the wall/background.

    const y = Math.min(Math.max(Math.round(anchors.y), 0), genImg.height - 1);
    // Scan a few lines around the anchor Y to catch the awning body/frame
    // We start slightly below the anchor Y to avoid the very top edge blending with wall
    const yStart = Math.min(genImg.height - 1, Math.max(0, y + 2));
    const yEnd = Math.min(genImg.height - 1, yStart + 12);

    // Define background sample regions (approx 40px outside the expected anchors)
    // We use the generated image itself to find "what the wall looks like now"
    const bgLeftX = Math.max(0, Math.round(anchors.x_left) - 40);
    const bgRightX = Math.min(genImg.width - 1, Math.round(anchors.x_right) + 40);

    // Sample background color (average of a vertical strip to reduce noise)
    let bgR = 0, bgG = 0, bgB = 0, count = 0;
    for (let yy = yStart; yy <= yEnd; yy++) {
      const c1 = genImg.getPixelAt(bgLeftX, yy);
      const c2 = genImg.getPixelAt(bgRightX, yy);
      bgR += ((c1 >> 24) & 0xFF) + ((c2 >> 24) & 0xFF);
      bgG += ((c1 >> 16) & 0xFF) + ((c2 >> 16) & 0xFF);
      bgB += ((c1 >> 8) & 0xFF) + ((c2 >> 8) & 0xFF);
      count += 2;
    }
    bgR = Math.round(bgR / count);
    bgG = Math.round(bgG / count);
    bgB = Math.round(bgB / count);

    const threshold = 35; // Sensitivity to color change vs wall

    let left = -1;
    let right = -1;

    // Search range: generous around the anchors
    const searchMin = Math.max(0, Math.round(anchors.x_left) - 100);
    const searchMax = Math.min(genImg.width - 1, Math.round(anchors.x_right) + 100);

    for (let x = searchMin; x <= searchMax; x++) {
      let isAwning = 0;
      for (let yy = yStart; yy <= yEnd; yy++) {
        const c = genImg.getPixelAt(x, yy);
        const r = (c >> 24) & 0xFF, g = (c >> 16) & 0xFF, b = (c >> 8) & 0xFF;
        const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
        if (diff > threshold) isAwning++;
      }

      // If more than 40% of the vertical pixels differ from background, it's awning
      if (isAwning > (yEnd - yStart + 1) * 0.4) {
        if (left === -1) left = x;
        right = x;
      }
    }

    if (left === -1 || right === -1) return null;

    // Filter noise: Awning must be at least 20px wide
    if ((right - left) < 20) return null;

    return { x_left: left, x_right: right, width_px: right - left };
  } catch (_) {
    return null;
  }
}

// NEW: Measure the Y position (top and bottom) of the awning to verify vertical placement and define ROI
async function measureAwningYPosition(baseBase64: string, genBase64: string, expectedAnchors: { x_left: number; x_right: number; y: number }) {
  try {
    const baseImg = await Image.decode(base64ToBytes(baseBase64));
    const genImg = await Image.decode(base64ToBytes(genBase64));

    if (baseImg.width !== genImg.width || baseImg.height !== genImg.height) {
      return null; // Images must match
    }

    // Scan vertically to find where the generated image differs from base (awning added)
    // We look in the horizontal center region of the expected awning area
    const centerX = Math.round((expectedAnchors.x_left + expectedAnchors.x_right) / 2);
    const scanWidth = Math.min(100, Math.round((expectedAnchors.x_right - expectedAnchors.x_left) / 3));

    let topY = -1;
    let bottomY = -1;
    const threshold = 50; // RGB diff threshold to detect change

    // 1. Find TOP edge: Scan from top of image downward
    for (let y = 1; y <= genImg.height; y++) {
      let diffCount = 0;
      for (let x = Math.max(1, centerX - scanWidth); x <= Math.min(genImg.width, centerX + scanWidth); x++) {
        const baseColor = baseImg.getPixelAt(x, y);
        const genColor = genImg.getPixelAt(x, y);
        const diff = rgbDiff(baseColor, genColor);
        if (diff > threshold) {
          diffCount++;
        }
      }
      // If more than 30% of pixels in this row differ, this is likely the top of the awning
      if (diffCount > scanWidth * 2 * 0.3) {
        topY = y;
        break;
      }
    }

    // 2. Find BOTTOM edge: Scan from topY downwards until diff disappears
    if (topY > 0) {
      // Assume awning is at least 50px tall, start checking for bottom after some buffer
      // Or just continue scanning until we hit a run of "clean" rows
      let consecutiveCleanRows = 0;
      const requiredCleanRows = 20; // How many rows of "no diff" to confirm bottom

      for (let y = topY + 10; y <= genImg.height; y++) {
        let diffCount = 0;
        for (let x = Math.max(1, centerX - scanWidth); x <= Math.min(genImg.width, centerX + scanWidth); x++) {
          const baseColor = baseImg.getPixelAt(x, y);
          const genColor = genImg.getPixelAt(x, y);
          const diff = rgbDiff(baseColor, genColor);
          if (diff > threshold) {
            diffCount++;
          }
        }

        if (diffCount < scanWidth * 2 * 0.1) { // Less than 10% diff (clean row)
          consecutiveCleanRows++;
          if (consecutiveCleanRows >= requiredCleanRows) {
            bottomY = y - requiredCleanRows;
            break;
          }
        } else {
          consecutiveCleanRows = 0; // Reset if we hit a diff row
          bottomY = y; // Update potential bottom to current row
        }
      }

      // If we reached bottom of image without finding clean region, assume bottom is image height
      if (bottomY === -1) bottomY = genImg.height;
    }

    return topY > 0 ? { y_top: topY, y_bottom: bottomY } : null;
  } catch (_) {
    return null;
  }
}

async function getRedLineBoundingBox(base64: string) {
  try {
    const img = await Image.decode(base64ToBytes(base64));
    let minX = img.width, minY = img.height, maxX = 0, maxY = 0;
    let found = false;
    for (let y = 0; y < img.height; y++) {
      for (let x = 0; x < img.width; x++) {
        const color = img.getPixelAt(x, y);
        const r = (color >> 24) & 0xFF;
        const g = (color >> 16) & 0xFF;
        const b = (color >> 8) & 0xFF;
        if (r > 200 && g < 50 && b < 50) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
          found = true;
        }
      }
    }
    if (!found) return null;
    const paddingX = Math.round(img.width * 0.25); // Increased to 25% for context
    const paddingAbove = Math.round(img.height * 0.15); // Increased to 15%
    const paddingBelow = Math.round(img.height * 0.40); // Increased to 40% to include windows for context
    
    let x = Math.max(0, minX - paddingX);
    let w = Math.min(img.width - x, (maxX - minX) + (paddingX * 2));
    let y = Math.max(0, minY - paddingAbove);
    let h = Math.min(img.height - y, (maxY - minY) + paddingAbove + paddingBelow);
    
    // ADJUST CROP TO MATCH A SUPPORTED ASPECT RATIO EXACTLY
    // Supported ARs: 1:1, 2:3, 3:2, 3:4, 4:3, 4:5, 5:4, 9:16, 16:9, 21:9
    const targetARs = [1, 2/3, 3/2, 3/4, 4/3, 4/5, 5/4, 9/16, 16/9, 21/9];
    const currentAR = w / h;
    let bestAR = 1;
    let minDiff = Infinity;
    
    for (const ar of targetARs) {
      const diff = Math.abs(currentAR - ar);
      if (diff < minDiff) {
        minDiff = diff;
        bestAR = ar;
      }
    }
    
    // Adjust dimensions to match bestAR by EXPANDING
    if (currentAR > bestAR) {
        // Too wide, need to increase height
        const targetH = Math.round(w / bestAR);
        const diffH = targetH - h;
        // Add height equally top/bottom if possible, but favor bottom (more context)
        const addTop = Math.floor(diffH * 0.3); 
        const addBottom = diffH - addTop;
        
        y = Math.max(0, y - addTop);
        // Recalculate h based on new y, but limited by image height
        h = Math.min(img.height - y, h + addBottom + addTop);
        
        // If hit boundaries, we might need to shrink width to maintain AR, but better to just accept slight mismatch than lose content
        // Or re-adjust width? Let's just try to get close.
    } else {
        // Too tall (or narrow), need to increase width
        const targetW = Math.round(h * bestAR);
        const diffW = targetW - w;
        const addLeft = Math.floor(diffW / 2);
        const addRight = diffW - addLeft;
        
        x = Math.max(0, x - addLeft);
        w = Math.min(img.width - x, w + addRight + addLeft);
    }
    
    // Final check to ensure we didn't go out of bounds
    w = Math.min(w, img.width - x);
    h = Math.min(h, img.height - y);
    
    return { x, y, w, h };
  } catch (e) {
    console.error("Error calculating red line bounding box:", e);
    return null;
  }
}

async function cropImageToBase64(base64: string, box: { x: number; y: number; w: number; h: number }) {
  const img = await Image.decode(base64ToBytes(base64));
  const cropped = img.crop(box.x, box.y, box.w, box.h);
  const bytes = await cropped.encode();
  let binary = '';
  const len = bytes.byteLength;
  const chunkSize = 32768;
  for (let i = 0; i < len; i += chunkSize) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize) as any);
  }
  return btoa(binary);
}

async function overlayCompositeToBase64(originalBase64: string, generatedCropBase64: string, box: { x: number; y: number; w: number; h: number }) {
  const origImg = await Image.decode(base64ToBytes(originalBase64));
  let genImg = await Image.decode(base64ToBytes(generatedCropBase64));
  if (genImg.width !== box.w || genImg.height !== box.h) {
    genImg = genImg.resize(box.w, box.h);
  }
  origImg.composite(genImg, box.x, box.y);
  const bytes = await origImg.encode();
  let binary = '';
  const len = bytes.byteLength;
  const chunkSize = 32768;
  for (let i = 0; i < len; i += chunkSize) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize) as any);
  }
  return btoa(binary);
}

// Fast full-image overlay when diff-based compositing would exceed CPU budget
async function overlayCompositeFullToBase64(originalBase64: string, generatedBase64: string) {
  const origImg = await Image.decode(base64ToBytes(originalBase64));
  let genImg = await Image.decode(base64ToBytes(generatedBase64));
  if (genImg.width !== origImg.width || genImg.height !== origImg.height) {
    genImg = genImg.resize(origImg.width, origImg.height);
  }
  origImg.composite(genImg, 0, 0);
  const bytes = await origImg.encode();
  let binary = '';
  const len = bytes.byteLength;
  const chunkSize = 32768;
  for (let i = 0; i < len; i += chunkSize) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize) as any);
  }
  return btoa(binary);
}

async function smartCompositeDiffCropToBase64(originalBase64: string, generatedCropBase64: string, box: { x: number; y: number; w: number; h: number }, diffThreshold = 40) {
  const timeStart = Date.now();
  const origImg = await Image.decode(base64ToBytes(originalBase64));
  let genImg = await Image.decode(base64ToBytes(generatedCropBase64));
  if (genImg.width !== box.w || genImg.height !== box.h) {
    genImg = genImg.resize(box.w, box.h);
  }
  const crop = origImg.crop(box.x, box.y, box.w, box.h);
  const width = box.w;
  const height = box.h;
  const mask = new Uint8Array(width * height);
  for (let y = 1; y <= height; y++) {
    // TIMEOUT GUARD: abort diff-building if > 6s
    if (y % 100 === 0 && (Date.now() - timeStart) > 6000) {
      console.warn(`[WARN] smartCompositeDiffCrop: diff build timed out at row ${y}/${height}. Falling back to simple overlay.`);
      // Fallback to simple overlay to avoid CPU kill
      const bytes = await overlayCompositeToBase64(originalBase64, generatedCropBase64, box);
      return bytes;
    }
    for (let x = 1; x <= width; x++) {
      const c0 = crop.getPixelAt(x, y);
      const c1 = genImg.getPixelAt(x, y);
      const r0 = (c0 >> 24) & 0xFF, g0 = (c0 >> 16) & 0xFF, b0 = (c0 >> 8) & 0xFF;
      const r1 = (c1 >> 24) & 0xFF, g1 = (c1 >> 16) & 0xFF, b1 = (c1 >> 8) & 0xFF;
      const dist = Math.abs(r1 - r0) + Math.abs(g1 - g0) + Math.abs(b1 - b0);
      if (dist > diffThreshold) {
        mask[(y - 1) * width + (x - 1)] = 1;
      }
    }
  }
  for (let y = 1; y <= height; y++) {
    // TIMEOUT GUARD: abort masked copy if > 9s
    if (y % 100 === 0 && (Date.now() - timeStart) > 9000) {
      console.warn(`[WARN] smartCompositeDiffCrop: masked copy timed out at row ${y}/${height}. Falling back to simple overlay.`);
      const bytes = await overlayCompositeToBase64(originalBase64, generatedCropBase64, box);
      return bytes;
    }
    for (let x = 1; x <= width; x++) {
      const idx = (y - 1) * width + (x - 1);
      if (mask[idx]) {
        const c1 = genImg.getPixelAt(x, y);
        origImg.setPixelAt(box.x + x, box.y + y, c1);
      }
    }
  }
  const kernel = [
    [0, -1, 0],
    [-1, 5, -1],
    [0, -1, 0]
  ];
  for (let y = 2; y <= height - 1; y++) {
    // TIMEOUT GUARD: abort sharpening step if > 11s
    if (y % 100 === 0 && (Date.now() - timeStart) > 11000) {
      console.warn(`[WARN] smartCompositeDiffCrop: sharpening timed out at row ${y}/${height}. Skipping remaining sharpening.`);
      break;
    }
    for (let x = 2; x <= width - 1; x++) {
      const idx = (y - 1) * width + (x - 1);
      if (!mask[idx]) continue;
      let sr = 0, sg = 0, sb = 0;
      for (let ky = -1; ky <= 1; ky++) {
        for (let kx = -1; kx <= 1; kx++) {
          const c = origImg.getPixelAt(box.x + x + kx, box.y + y + ky);
          const r = (c >> 24) & 0xFF, g = (c >> 16) & 0xFF, b = (c >> 8) & 0xFF;
          const w = kernel[ky + 1][kx + 1];
          sr += r * w; sg += g * w; sb += b * w;
        }
      }
      const nr = Math.max(0, Math.min(255, Math.round(sr)));
      const ng = Math.max(0, Math.min(255, Math.round(sg)));
      const nb = Math.max(0, Math.min(255, Math.round(sb)));
      origImg.setPixelAt(box.x + x, box.y + y, Image.rgbaToColor(nr, ng, nb, 255));
    }
  }
  // TIMEOUT GUARD: final encode budget
  if ((Date.now() - timeStart) > 13000) {
    console.warn(`[WARN] smartCompositeDiffCrop: encode budget exceeded (${Date.now() - timeStart}ms). Returning simple overlay result.`);
    const bytes = await overlayCompositeToBase64(originalBase64, generatedCropBase64, box);
    return bytes;
  }
  const bytes = await origImg.encode();
  let binary = '';
  const len = bytes.byteLength;
  const chunkSize = 32768;
  for (let i = 0; i < len; i += chunkSize) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize) as any);
  }
  return btoa(binary);
}

